function render(items){const host=$("#emptyState");if(!host)return;host.onclick=e=>{const store=e.target.closest(".store-link");if(store){openStore(store.dataset.store);return}const add=e.target.closest(".add-cart"),fav=e.target.closest(".favorite-toggle"),detail=e.target.closest(".product-detail");if(add){addCart(add.dataset.id);return}if(fav){const id=String(fav.dataset.favorite);let ids=JSON.parse(localStorage.getItem("cercasv_favorites")||"[]");ids=ids.includes(id)?ids.filter(x=>x!==id):[...ids,id];localStorage.setItem("cercasv_favorites",JSON.stringify(ids));fav.textContent=ids.includes(id)?"♥ Guardado":"♡ Favoritos";fav.classList.toggle("is-saved",ids.includes(id));notify(ids.includes(id)?"Añadido a favoritos":"Quitado de favoritos");return}if(detail){const p=products.find(x=>String(x.id)===detail.dataset.id);if(p)productDetail(p)}};const count=$("#catalogCount");if(count)count.textContent=items.length+" producto"+(items.length===1?"":"s");const favorites=new Set(JSON.parse(localStorage.getItem("cercasv_favorites")||"[]").map(String));if(!items.length){host.className="empty-products catalog-empty";host.innerHTML='<div class="big">🛍️</div><h3>No encontramos productos</h3><p>Prueba cambiar la búsqueda, quitar algún filtro o explorar otras categorías.</p><button class="btn btn-outline" id="clearCatalogFilters">Limpiar filtros</button>';$("#clearCatalogFilters")?.addEventListener("click",clearCatalogFilters);return}host.className="product-grid";host.innerHTML=items.map(p=>'<article class="product-card catalog-card"><button class="favorite-toggle '+(favorites.has(String(p.id))?"is-saved":"")+'" data-favorite="'+esc(p.id)+'" aria-label="Guardar en favoritos">'+(favorites.has(String(p.id))?"♥":"♡")+'</button><button class="product-detail" data-id="'+esc(p.id)+'" aria-label="Ver detalles de '+esc(p.nombre)+'"><div class="product-symbol">'+(p.imagen_url?'<img src="'+esc(p.imagen_url)+'" alt="'+esc(p.nombre)+'" loading="lazy" decoding="async" referrerpolicy="no-referrer">':'<span class="product-placeholder">🛍️</span>')+'</div><div class="catalog-card-info"><button type="button" class="product-store store-link" data-store="'+esc(p.negocio_id||p.negocios?.id||"")+'">'+esc(p.negocios?.nombre||"Negocio local")+'</button><h3>'+esc(p.nombre)+'</h3><strong>'+money(p.precio)+'</strong><span class="stock">'+(Number(p.stock)>0?"Disponible":"Agotado")+'</span></div></button><button class="btn btn-primary add-cart" data-id="'+esc(p.id)+'" '+(Number(p.stock)<=0?"disabled":"")+'>'+(Number(p.stock)>0?"Agregar al carrito":"Agotado")+'</button></article>').join("")}
async function openStore(storeId){
 if(!storeId){notify("No se encontró la tienda.");return}
 modal("Cargando tienda",'<div class="store-loading"><span class="store-loader"></span><p>Estamos preparando esta tienda…</p></div>',{fullScreen:true});
 let cached=storeCache.get(String(storeId));
 let shop,items,error,itemsError;
 if(cached&&Date.now()-cached.time<60000){shop=cached.shop;items=cached.items;error=null;itemsError=null}
 else{
  const [shopResult,itemsResult]=await Promise.all([
   db.from("negocios").select("id,nombre,descripcion,municipio,departamento,telefono,categoria,modalidad_atencion,logo_url,portada_url,estado").eq("id",storeId).maybeSingle(),
   db.from("productos").select("id,negocio_id,nombre,descripcion,precio,stock,imagen_url,imagenes,categoria_id,creado_en,negocios(id,nombre,municipio,departamento),categorias(nombre)").eq("negocio_id",storeId).eq("activo",true).gt("stock",0).order("creado_en",{ascending:false})
  ]);
  shop=shopResult.data;items=itemsResult.data;error=shopResult.error;itemsError=itemsResult.error;
  if(!error&&shop)storeCache.set(String(storeId),{shop,items:items||[],time:Date.now()});
 }
 if(error||!shop){notify(error?.message||"No encontramos esta tienda.");$("#modal")?.remove();document.body.classList.remove("modal-open");return}
 if(itemsError){console.error("Store products:",itemsError);notify("No se pudieron cargar los productos de esta tienda.");}
 const list=items||[],cats=["Todos",...new Set(list.map(x=>x.categorias?.nombre).filter(Boolean))];
 const location=[shop.municipio,shop.departamento].filter(Boolean).join(", ");
 const delivery=shop.modalidad_atencion==="delivery"?"Delivery":shop.modalidad_atencion==="recogida"?"Recogida en local":shop.modalidad_atencion==="ambas"?"Delivery y recogida":"";
 const logo=shop.logo_url||shop.imagen_url||"",cover=shop.portada_url||shop.banner_url||"";
 const root=$("#modal .modal-content");if(!root)return;
 root.innerHTML='<div class="storefront"><div class="store-cover" '+(cover?'style="background-image:linear-gradient(90deg,rgba(8,43,101,.72),rgba(8,43,101,.12)),url(&quot;'+esc(cover)+'&quot;)"':'')+'><span>TIENDA LOCAL · CERCASV</span></div><div class="store-profile"><div class="store-avatar">'+(logo?'<img src="'+esc(logo)+'" alt="Logo de '+esc(shop.nombre)+'">':'<span>'+esc((shop.nombre||"T").trim().charAt(0).toUpperCase())+'</span>')+'</div><div class="store-identity"><h3>'+esc(shop.nombre)+'</h3><p>'+esc(shop.categoria||"Negocio local")+(location?" · "+esc(location):"")+'</p></div></div><div class="store-description">'+esc(shop.descripcion||"Descubre los productos de este negocio local.")+'</div><div class="store-facts">'+(delivery?'<span>↗ '+esc(delivery)+'</span>':"")+(shop.telefono?'<span>☎ '+esc(shop.telefono)+'</span>':"")+(location?'<span>⌖ '+esc(location)+'</span>':"")+'</div><div class="store-catalog-head"><div><h4>Productos de la tienda</h4><small>'+list.length+' producto'+(list.length===1?"":"s")+' disponible'+(list.length===1?"":"s")+'</small></div><label>Ordenar <select id="storeSort"><option value="newest">Recientes</option><option value="price-asc">Menor precio</option><option value="price-desc">Mayor precio</option><option value="name">Nombre A–Z</option></select></label></div><div class="store-category-tabs" id="storeCategories">'+cats.map((cat,i)=>'<button type="button" class="'+(i===0?"active":"")+'" data-store-category="'+esc(cat)+'">'+esc(cat)+'</button>').join("")+'</div><div class="store-product-grid" id="storeProducts">'+(list.length?list.map(storeProductCard).join(""):'<div class="empty-products"><h3>Esta tienda aún no tiene productos</h3><p>Vuelve pronto para descubrir sus novedades.</p></div>')+'</div></div>';
 let category="Todos",sort="newest";
 const draw=()=>{let visible=list.filter(x=>category==="Todos"||x.categorias?.nombre===category);if(sort==="price-asc")visible.sort((x,y)=>Number(x.precio)-Number(y.precio));else if(sort==="price-desc")visible.sort((x,y)=>Number(y.precio)-Number(x.precio));else if(sort==="name")visible.sort((x,y)=>String(x.nombre).localeCompare(String(y.nombre),"es"));else visible.sort((x,y)=>new Date(y.creado_en||0)-new Date(x.creado_en||0));const host=$("#storeProducts");if(host)host.innerHTML=visible.length?visible.map(storeProductCard).join(""):'<div class="empty-products"><h3>No hay productos en esta categoría</h3><p>Prueba otra categoría.</p></div>'};
 $("#storeCategories")?.addEventListener("click",e=>{const btn=e.target.closest("[data-store-category]");if(!btn)return;category=btn.dataset.storeCategory;$("#storeCategories").querySelectorAll("button").forEach(x=>x.classList.toggle("active",x===btn));draw()});
 $("#storeSort")?.addEventListener("change",e=>{sort=e.target.value;draw()});
 $("#storeProducts")?.addEventListener("click",e=>{const add=e.target.closest("[data-store-add]"),detail=e.target.closest("[data-store-detail]");if(add){addCart(add.dataset.storeAdd);return}if(detail){const product=list.find(x=>String(x.id)===detail.dataset.storeDetail);if(product)productDetail(product)}});
}
function storeProductCard(p){return '<article class="store-product-card"><button type="button" class="store-product-open" data-store-detail="'+esc(p.id)+'"><div class="store-product-image">'+(p.imagen_url?'<img src="'+esc(p.imagen_url)+'" alt="'+esc(p.nombre)+'" loading="lazy" decoding="async" fetchpriority="low">':'<span>🛍️</span>')+'</div><b>'+esc(p.nombre)+'</b><strong>'+money(p.precio)+'</strong></button><button type="button" class="btn btn-primary" data-store-add="'+esc(p.id)+'">Agregar</button></article>'}
function productDetail(p){const saved=JSON.parse(localStorage.getItem("cercasv_favorites")||"[]").map(String).includes(String(p.id)),photos=[...new Set([...(p.imagenes||[]),...(p.imagen_url?[p.imagen_url]:[])])];modal("Detalle del producto",'<div class="product-detail-view"><div class="product-detail-image" id="detailMainImage">'+(photos[0]?'<img src="'+esc(photos[0])+'" alt="'+esc(p.nombre)+'">':'<span>🛍️</span>')+'</div><div class="product-detail-gallery">'+photos.map((url,i)=>'<button type="button" data-detail-photo="'+i+'" class="'+(i===0?"active":"")+'"><img src="'+esc(url)+'" alt="Foto '+(i+1)+'"></button>').join("")+'</div><button type="button" class="product-store store-link" id="detailStore" data-store="'+esc(p.negocio_id||p.negocios?.id||"")+'">'+esc(p.negocios?.nombre||"Negocio local")+' · '+esc([p.negocios?.municipio,p.negocios?.departamento].filter(Boolean).join(", "))+'</button><h3>'+esc(p.nombre)+'</h3><strong class="product-detail-price">'+money(p.precio)+'</strong><p>'+esc(p.descripcion||"Consulta directamente con el negocio para conocer más detalles de este producto.")+'</p><p class="product-detail-stock">'+(Number(p.stock)>0?"Disponibles: "+Number(p.stock):"Producto agotado")+'</p><div class="product-detail-actions"><button class="btn btn-outline" id="detailFavorite">'+(saved?"♥ Guardado":"♡ Guardar favorito")+'</button><button class="btn btn-primary" id="detailAdd" '+(Number(p.stock)<=0?"disabled":"")+'>'+(Number(p.stock)>0?"Agregar al carrito":"Agotado")+'</button></div></div>');$("#modal")?.querySelectorAll("[data-detail-photo]").forEach(b=>b.onclick=()=>{$("#detailMainImage").innerHTML='<img src="'+esc(photos[Number(b.dataset.detailPhoto)])+'" alt="'+esc(p.nombre)+'">';$("#modal").querySelectorAll("[data-detail-photo]").forEach(x=>x.classList.toggle("active",x===b))});$("#detailStore")?.addEventListener("click",()=>openStore(p.negocio_id||p.negocios?.id));$("#detailFavorite")?.addEventListener("click",()=>{let ids=JSON.parse(localStorage.getItem("cercasv_favorites")||"[]").map(String);ids=ids.includes(String(p.id))?ids.filter(x=>x!==String(p.id)):[...ids,String(p.id)];localStorage.setItem("cercasv_favorites",JSON.stringify(ids));$("#detailFavorite").textContent=ids.includes(String(p.id))?"♥ Guardado":"♡ Guardar favorito";notify(ids.includes(String(p.id))?"Añadido a favoritos":"Quitado de favoritos")});$("#detailAdd")?.addEventListener("click",()=>{addCart(p.id);$("#modal")?.remove();document.body.classList.remove("modal-open")})}

async function load(){const pageSize=500;let all=[],from=0;while(true){const {data,error}=await db.from("productos").select("id,negocio_id,nombre,descripcion,precio,stock,imagen_url,imagenes,categoria_id,negocios(id,nombre,municipio,departamento),categorias(nombre)").eq("activo",true).gt("stock",0).order("creado_en",{ascending:false}).order("id",{ascending:true}).range(from,from+pageSize-1);if(error){console.error(error);notify("No se pudo cargar el catálogo.");return}const page=data||[];all=all.concat(page);if(page.length<pageSize)break;from+=pageSize}products=all;storeCache.clear();filter()}
let catalogMinPrice="",catalogMaxPrice="",catalogSort="newest";
function filter(){const input=$("#searchInput"),q=(input?.value||"").trim().toLowerCase();let loc;try{loc=JSON.parse(localStorage.getItem("cercasv_location")||'{"departamento":"Cabañas","municipio":"Ilobasco"}')}catch{loc={}}let list=products.filter(p=>(activeCategory==="Todo"||p.categorias?.nombre===activeCategory)&&(!loc.departamento||p.negocios?.departamento===loc.departamento)&&(!loc.municipio||p.negocios?.municipio?.toLowerCase()===loc.municipio.toLowerCase())&&(p.nombre+" "+(p.descripcion||"")+" "+(p.negocios?.nombre||"")+" "+(p.categorias?.nombre||"")).toLowerCase().includes(q)&&(!catalogMinPrice||Number(p.precio)>=Number(catalogMinPrice))&&(!catalogMaxPrice||Number(p.precio)<=Number(catalogMaxPrice)));if(catalogSort==="price-asc")list.sort((a,b)=>Number(a.precio)-Number(b.precio));else if(catalogSort==="price-desc")list.sort((a,b)=>Number(b.precio)-Number(a.precio));else if(catalogSort==="name")list.sort((a,b)=>String(a.nombre).localeCompare(String(b.nombre),"es"));else list.sort((a,b)=>new Date(b.creado_en||0)-new Date(a.creado_en||0));render(list);const active=$("#catalogActiveFilters");if(active){const tags=[];if(activeCategory!=="Todo")tags.push(activeCategory);if(catalogMinPrice)tags.push("Desde "+money(catalogMinPrice));if(catalogMaxPrice)tags.push("Hasta "+money(catalogMaxPrice));active.innerHTML=tags.map(x=>'<span class="active-filter-tag">'+esc(x)+'</span>').join("")+(tags.length?'<button type="button" id="clearActiveCatalog">Limpiar</button>':"");$("#clearActiveCatalog")?.addEventListener("click",clearCatalogFilters)}}
function clearCatalogFilters(){catalogMinPrice="";catalogMaxPrice="";activeCategory="Todo";document.querySelectorAll(".chip").forEach(x=>x.classList.toggle("active",x.textContent.trim()==="Todo"));const sort=$("#catalogSort");if(sort)sort.value="newest";filter()}
function openCatalogFilters(){modal("Filtrar productos",'<form id="catalogFilterForm" class="form-grid"><p>Encuentra productos dentro del presupuesto que tienes en mente.</p><div class="catalog-price-fields"><label>Precio mínimo (USD)<input name="min" type="number" min="0" step="0.01" placeholder="Ej. 5" value="'+esc(catalogMinPrice)+'"></label><label>Precio máximo (USD)<input name="max" type="number" min="0" step="0.01" placeholder="Ej. 50" value="'+esc(catalogMaxPrice)+'"></label></div><button class="btn btn-primary" type="submit">Aplicar filtros</button><button class="btn btn-outline" type="button" id="resetCatalogFilters">Limpiar filtros</button></form>');$("#catalogFilterForm")?.addEventListener("submit",e=>{e.preventDefault();const fd=new FormData(e.currentTarget),min=String(fd.get("min")||"").trim(),max=String(fd.get("max")||"").trim();if(min&&Number(min)<0||max&&Number(max)<0){notify("Los precios no pueden ser negativos.");return}if(min&&max&&Number(min)>Number(max)){notify("El precio mínimo no puede superar el máximo.");return}catalogMinPrice=min;catalogMaxPrice=max;$("#modal")?.remove();document.body.classList.remove("modal-open");filter()});$("#resetCatalogFilters")?.addEventListener("click",()=>{catalogMinPrice="";catalogMaxPrice="";$("#modal")?.remove();document.body.classList.remove("modal-open");filter()})}

async function refreshAuth(){const {data,error}=await db.auth.getSession();if(error){console.error(error);user=null;profile=null;updateNav();return}user=data.session?.user||null;profile=null;if(user){const r=await db.from("perfiles").select("*").eq("id",user.id).maybeSingle();if(r.error)console.error(r.error);profile=r.data||null}updateNav()}
function updateNav(){const login=$("#loginBtn");if(login){login.textContent=user?"Mi cuenta":"Ingresar";login.title=user?"Mi cuenta":"Ingresar";login.onclick=()=>user?accountMenu():authModal();}const admin=$("#adminNavBtn");if(admin)admin.remove();const seller=$("#sellerBtn");if(seller){seller.textContent=user?"＋ Vender":"Iniciar sesión para vender";seller.onclick=()=>user?sellerPanel():authModal("registro");}const cartButton=$("#cartBtn");if(cartButton)cartButton.onclick=cartModal;const businessTab=$("#bottomBusiness");if(businessTab){businessTab.hidden=!user||!hasRole("vendedor");}
saveCart()}
function authModal(mode="login"){modal(mode==="registro"?"Crear cuenta CercaSV":"Ingresar a CercaSV",'<form id="authForm" class="form-grid"><label>Correo<input name="email" type="email" required autocomplete="email"></label><label>Contraseña<input name="password" type="password" minlength="6" required autocomplete="'+(mode==="registro"?"new-password":"current-password")+'"></label>'+(mode==="registro"?'<label>Nombre completo<input name="nombre" required></label>':'')+'<button class="btn btn-primary" type="submit">'+(mode==="registro"?"Crear cuenta":"Ingresar")+'</button><button class="btn btn-outline" type="button" id="switchAuth">'+(mode==="registro"?"Ya tengo cuenta":"Crear cuenta")+'</button>'+(mode==="login"?'<button class="btn btn-outline" type="button" id="forgotPassword">Olvidé mi contraseña</button>':'')+'</form>');
if($("#switchAuth"))$("#switchAuth").onclick=()=>authModal(mode==="registro"?"login":"registro");if(mode==="login"){if($("#forgotPassword"))$("#forgotPassword").onclick=async()=>{const email=$("#authForm").elements.email.value.trim();if(!email){notify("Escribe tu correo para enviarte el enlace.");$("#authForm").elements.email.focus();return}const {error}=await db.auth.resetPasswordForEmail(email,{redirectTo:window.location.origin});if(error)notify(error.message);else notify("Si existe una cuenta con ese correo, recibirás un enlace para recuperar la contraseña.")}};$("#authForm").onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),email=fd.get("email"),password=fd.get("password");let result;if(mode==="registro"){result=await db.auth.signUp({email,password,options:{emailRedirectTo:window.location.origin+window.location.pathname,data:{nombre_completo:fd.get("nombre"),rol:"comprador"}}});if(!result.error&&result.data.user){const {error}=await db.from("perfiles").upsert({id:result.data.user.id,nombre_completo:fd.get("nombre"),correo:email,rol:"comprador",roles:["comprador"]});if(error)console.error(error)}}else result=await db.auth.signInWithPassword({email,password});if(result.error){notify(result.error.message);return}if(mode==="registro"&&!result.data.session){$("#modal").remove();confirmationModal(email);return}if(mode==="login"&&result.data.user&&!result.data.user.email_confirmed_at){await db.auth.signOut();user=null;profile=null;updateNav();$("#modal").remove();confirmationModal(email);notify("Confirma tu correo antes de iniciar sesión.");return}$("#modal").remove();await refreshAuth();notify(mode==="registro"?"Cuenta creada. Si te pide confirmar correo, revisa tu bandeja.":"Sesión iniciada");if(hasRole("vendedor"))sellerPanel()}}
function confirmationModal(email){
modal("Confirma tu correo",'<p>Te enviamos un enlace de confirmación a <b>'+esc(email)+'</b>. Abre ese enlace para activar tu cuenta.</p><button class="btn btn-primary" id="resendConfirmation">Reenviar correo</button><button class="btn btn-outline" id="backToLogin">Volver a ingresar</button>');
if($("#resendConfirmation"))$("#resendConfirmation").onclick=async()=>{const {error}=await db.auth.resend({type:"signup",email,options:{emailRedirectTo:window.location.origin+window.location.pathname}});if(error)notify(error.message);else notify("Si el correo puede reenviarse, recibirás un nuevo enlace.");};
if($("#backToLogin"))$("#backToLogin").onclick=()=>authModal("login");
}
async function handlePasswordRecovery(){const hash=new URLSearchParams(window.location.hash.slice(1));const query=new URLSearchParams(window.location.search);if(hash.get("error")||query.get("error")){const message=hash.get("error_description")||query.get("error_description")||"El enlace no es válido o expiró.";modal("Enlace de recuperación",'<p>'+esc(message.replace(/\+/g," "))+'</p>'+ '<button class="btn btn-primary" id="retryRecovery">Solicitar otro enlace</button>');if($("#retryRecovery"))$("#retryRecovery").onclick=()=>{history.replaceState(null,"",window.location.pathname);authModal("login")};return}if(hash.get("type")!=="recovery")return;const {data,error}=await db.auth.getSession();if(error||!data.session){modal("Enlace de recuperación",'<p>La sesión de recuperación no está activa. Solicita un enlace nuevo e intenta de nuevo.</p><button class="btn btn-primary" id="retryRecovery">Solicitar otro enlace</button>');if($("#retryRecovery"))$("#retryRecovery").onclick=()=>{history.replaceState(null,"",window.location.pathname);authModal("login")};return}modal("Crear nueva contraseña",'<form id="newPasswordForm" class="form-grid"><label>Nueva contraseña<input name="password" type="password" minlength="6" required autocomplete="new-password"></label><button class="btn btn-primary">Guardar contraseña</button></form>');$("#newPasswordForm").onsubmit=async e=>{e.preventDefault();const password=new FormData(e.target).get("password");const btn=e.target.querySelector("button");btn.disabled=true;const {error}=await db.auth.updateUser({password});if(error){notify(error.message);btn.disabled=false;return}await db.auth.signOut();user=null;profile=null;updateNav();history.replaceState(null,"",window.location.pathname+window.location.search);$("#modal").remove();notify("Contraseña actualizada. Ingresa con tu nueva contraseña.")}}
