async function adminPanel(){if(!user||profile?.rol!=="admin"){notify("Acceso exclusivo de administrador.");return}const {data:shops,error}=await db.from("negocios").select("id,nombre,descripcion,municipio,departamento,estado,propietario_id,creado_en").order("creado_en",{ascending:false});if(error){notify("No se pudieron cargar negocios: "+error.message);return}const {data:items,error:pe}=await db.from("productos").select("id,nombre,precio,stock,activo,negocio_id").order("creado_en",{ascending:false});if(pe){notify("No se pudieron cargar productos: "+pe.message);return}const shopHtml=(shops||[]).map(s=>'<article class="seller-product"><b>'+esc(s.nombre)+'</b> · '+esc(s.estado)+'<p>'+esc(s.municipio)+', '+esc(s.departamento)+'</p><small>'+esc(s.descripcion||"")+'</small>'+(s.estado==="pendiente"?'<div><button data-approve="'+s.id+'">Aprobar</button> <button data-reject="'+s.id+'">Rechazar</button></div>':'')+'</article>').join("");const productHtml=(items||[]).map(p=>'<article class="seller-product">'+esc(p.nombre)+' · '+money(p.precio)+' · stock '+p.stock+' · '+(p.activo?"Activo":"Inactivo")+'</article>').join("");modal("Panel administrador",'<h3>Solicitudes y negocios</h3><div id="adminShops">'+(shopHtml||'<p>No hay negocios.</p>')+'</div><h3>Productos ('+(items||[]).length+')</h3><div id="adminProducts">'+productHtml+'</div>');$("#modal").querySelectorAll("[data-approve]").forEach(b=>b.onclick=()=>adminSetShop(b.dataset.approve,"aprobado"));$("#modal").querySelectorAll("[data-reject]").forEach(b=>b.onclick=()=>adminSetShop(b.dataset.reject,"rechazado"))}
async function adminSetShop(id,estado){const {data,error}=await db.from("negocios").update({estado}).eq("id",id).select("propietario_id").maybeSingle();if(error||!data){notify("No se pudo actualizar: "+(error?.message||"negocio no encontrado"));return}if(estado==="aprobado"){const {data:owner,error:readError}=await db.from("perfiles").select("rol,roles").eq("id",data.propietario_id).maybeSingle();if(readError||!owner){notify("Negocio aprobado, pero no se pudo leer el perfil.");return}const roles=Array.isArray(owner.roles)?owner.roles:owner.rol==="admin"?["comprador","vendedor","admin"]:owner.rol==="vendedor"?["comprador","vendedor"]:["comprador"];const nextRoles=[...new Set([...roles,"comprador","vendedor"])];const nextRol=nextRoles.includes("admin")?"admin":"vendedor";const {error:e}=await db.from("perfiles").update({roles:nextRoles,rol:nextRol}).eq("id",data.propietario_id);if(e)notify("Negocio aprobado, pero no se pudo actualizar roles: "+e.message);else notify("Negocio aprobado. Se conservaron los roles anteriores y se agregó vendedor")}else notify("Solicitud rechazada");adminPanel()}
function profilePanel(){if(!user){authModal();return}const name=profile?.nombre_completo||user.user_metadata?.nombre_completo||"";modal("Mi perfil",'<form id="profileForm" class="form-grid"><label>Nombre completo<input name="nombre" value="'+esc(name)+'" required maxlength="100"></label><label>Correo electrónico<input value="'+esc(user.email||"")+'" type="email" disabled></label><p>Para cambiar el correo se requiere un flujo de confirmación separado.</p><button class="btn btn-primary">Guardar perfil</button></form>');$("#profileForm").onsubmit=async e=>{e.preventDefault();const nombre=new FormData(e.target).get("nombre").trim();if(!nombre){notify("Escribe tu nombre completo.");return}const {data,error}=await db.from("perfiles").update({nombre_completo:nombre}).eq("id",user.id).select("id").maybeSingle();if(error||!data){notify("No se pudo guardar el perfil"+(error?": "+error.message:". No se encontró tu perfil."));return}profile={...(profile||{}),nombre_completo:nombre};if(user.user_metadata)user.user_metadata.nombre_completo=nombre;updateNav();$("#modal").remove();notify("Perfil actualizado")}}
function addCart(id){const p=products.find(x=>x.id===id);if(!p)return;let row=cart.find(x=>x.id===id);if(row)row.qty=Math.min(row.qty+1,p.stock);else cart.push({id,qty:1,name:p.nombre,price:p.precio,stock:p.stock,business:p.negocios?.nombre});saveCart();notify("Producto agregado al carrito")}
function cartModal(){if(!cart.length){modal("Tu carrito",'<p>Tu carrito está vacío. Explora el catálogo y agrega productos.</p>');return}modal("Tu carrito",'<div id="cartRows">'+cart.map(x=>'<div class="cart-row"><div><b>'+esc(x.name)+'</b><small>'+money(x.price)+' · '+esc(x.business)+'</small></div><div><button data-minus="'+x.id+'">−</button> '+x.qty+' <button data-plus="'+x.id+'">+</button> <button data-remove="'+x.id+'">×</button></div></div>').join("")+'</div><p class="total">Total productos: <b>'+money(cart.reduce((n,x)=>n+x.price*x.qty,0))+'</b></p><button class="btn btn-primary" id="checkout">Continuar compra</button>');$("#cartRows").querySelectorAll("[data-minus]").forEach(b=>b.onclick=()=>qty(b.dataset.minus,-1));$("#cartRows").querySelectorAll("[data-plus]").forEach(b=>b.onclick=()=>qty(b.dataset.plus,1));$("#cartRows").querySelectorAll("[data-remove]").forEach(b=>b.onclick=()=>{cart=cart.filter(x=>x.id!==b.dataset.remove);saveCart();cartModal()});if($("#checkout"))$("#checkout").onclick=()=>user?checkout():authModal()}
function qty(id,d){let p=cart.find(x=>x.id===id);if(!p)return;p.qty+=d;if(p.qty<=0)cart=cart.filter(x=>x.id!==id);else p.qty=Math.min(p.qty,p.stock);saveCart();cartModal()}
