function addressForm(a={}){modal(a.id?"Editar dirección":"Nueva dirección",'<form id="addressForm" class="form-grid"><label>Etiqueta<input name="etiqueta" value="'+esc(a.etiqueta||"Casa")+'" required></label><label>Departamento<input name="departamento" value="'+esc(a.departamento||"Cabañas")+'" required></label><label>Municipio<input name="municipio" value="'+esc(a.municipio||"Ilobasco")+'" required></label><label>Colonia<input name="colonia" value="'+esc(a.colonia||"")+'"></label><label>Dirección<input name="direccion" value="'+esc(a.direccion||"")+'" required></label><label>Referencias<textarea name="referencias">'+esc(a.referencias||"")+'</textarea></label><div id="map" class="map-box"></div><p>Selecciona el punto en el mapa o usa tu ubicación. Se guardan coordenadas solo si las eliges.</p><button type="button" id="locate" class="btn btn-outline">Usar mi ubicación</button><label><input type="checkbox" name="predeterminada" '+(a.predeterminada?"checked":"")+'> Dirección predeterminada</label><button class="btn btn-primary">Guardar dirección</button></form>');
let lat=a.latitud||13.8417,lng=a.longitud||-89.36,marker;const map=L.map("map").setView([lat,lng],13);L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{attribution:"© OpenStreetMap"}).addTo(map);function place(x,y){lat=x;lng=y;if(marker)marker.setLatLng([x,y]);else marker=L.marker([x,y]).addTo(map)}if(a.latitud&&a.longitud)place(lat,lng);map.on("click",e=>place(e.latlng.lat,e.latlng.lng));if($("#locate"))$("#locate").onclick=()=>navigator.geolocation?.getCurrentPosition(pos=>{lat=pos.coords.latitude;lng=pos.coords.longitude;map.setView([lat,lng],16);place(lat,lng)},()=>notify("No se pudo obtener ubicación. Revisa el permiso del navegador."));$("#addressForm").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),payload={usuario_id:user.id,etiqueta:f.get("etiqueta"),departamento:f.get("departamento"),municipio:f.get("municipio"),colonia:f.get("colonia"),direccion:f.get("direccion"),referencias:f.get("referencias"),predeterminada:f.has("predeterminada"),latitud:marker?lat:null,longitud:marker?lng:null};if(payload.predeterminada)await db.from("direcciones_entrega").update({predeterminada:false}).eq("usuario_id",user.id);let res=a.id?await db.from("direcciones_entrega").update(payload).eq("id",a.id).eq("usuario_id",user.id):await db.from("direcciones_entrega").insert(payload);if(res.error){notify(res.error.message);return}$("#modal").remove();notify("Dirección guardada")}}
async function checkout(){
 if(!user){authModal();return}
 const {data:addresses,error:addressError}=await db.from("direcciones_entrega").select("*").eq("usuario_id",user.id).order("predeterminada",{ascending:false});
 if(addressError||!addresses?.length){notify("Primero agrega una dirección de entrega.");addressPanel();return}
 if(!cart.length){notify("Tu carrito está vacío.");cartModal();return}
 const ids=cart.map(x=>x.id);
 const {data:liveProducts,error:productError}=await db.from("productos").select("id,negocio_id,nombre,precio,stock,activo").in("id",ids);
 if(productError){notify("No se pudo validar el catálogo. Intenta nuevamente.");return}
 const live=new Map((liveProducts||[]).map(p=>[String(p.id),p]));
 let changed=false;
 const nextCart=[];
 for(const item of cart){
  const p=live.get(String(item.id));
  if(!p||!p.activo||Number(p.stock)<=0){changed=true;continue}
  const qty=Math.min(Number(item.qty)||1,Number(p.stock));
  if(qty!==item.qty||Number(item.price)!==Number(p.precio)||item.name!==p.nombre||Number(item.stock)!==Number(p.stock))changed=true;
  nextCart.push({...item,qty,name:p.nombre,price:Number(p.precio),stock:Number(p.stock),business:item.business});
 }
 if(changed){
  cart=nextCart;saveCart();
  notify("El catálogo cambió. Revisa las cantidades y precios actualizados antes de continuar.");
  cartModal();return
 }
 const valid=cart.map(x=>({producto_id:x.id,cantidad:x.qty,negocio_id:live.get(String(x.id))?.negocio_id})).filter(x=>x.negocio_id);
 if(!valid.length){notify("No hay productos disponibles en el carrito.");cartModal();return}
 modal("Confirmar compra",'<p>El carrito se procesará en una sola operación. Cada vendedor recibirá su pedido por separado.</p><label>Dirección<select id="checkoutAddress">'+addresses.map(a=>'<option value="'+a.id+'">'+esc(a.etiqueta+' · '+a.municipio+' · '+a.direccion)+'</option>').join("")+'</select></label><label>Notas<textarea id="checkoutNotes"></textarea></label><p><b>Pago: contraentrega</b></p><p>El envío se calcula en Supabase usando la distancia entre la dirección y cada tienda.</p><button class="btn btn-primary" id="placeOrder">Confirmar compra</button>');
 if($("#placeOrder"))$("#placeOrder").onclick=async()=>{const btn=$("#placeOrder");btn.disabled=true;btn.textContent="Procesando…";const {data,error}=await db.rpc("crear_compra_multi",{p_direccion_id:$("#checkoutAddress").value,p_items:valid,p_notas:$("#checkoutNotes").value||null});if(error){notify(error.message);btn.disabled=false;btn.textContent="Confirmar compra";return}cart=[];saveCart();$("#modal").remove();notify("Compra enviada. Pago contraentrega.");ordersModal()}
}
 async function ordersModal(){if(!user)return authModal();const {data,error}=await db.from("pedidos").select("*,negocios(nombre),detalle_pedido(*)").eq("comprador_id",user.id).order("creado_en",{ascending:false});if(error){notify("No se pudieron cargar tus pedidos: "+error.message);return}const orders=data||[],steps=["recibido","aceptado","preparando","en_camino","entregado"],labels={recibido:"Pedido recibido",aceptado:"Aceptado por la tienda",preparando:"Preparando pedido",en_camino:"En camino",entregado:"Entregado",cancelado:"Cancelado"},renderOrder=o=>{const status=String(o.estado||"recibido"),idx=steps.indexOf(status),progress=status==="cancelado"?'<div class="order-progress cancelled"><span>Pedido cancelado</span></div>':'<div class="order-progress"><ol>'+steps.map((s,i)=>'<li class="'+(i<idx?"done":i===idx?"current":"")+'"><span>'+ (i<idx?"✓":i+1)+'</span><small>'+labels[s]+'</small></li>').join("")+'</ol></div>';return '<article class="order-card buyer-order"><div class="buyer-order-head"><b>Pedido '+esc(String(o.id).slice(0,8))+'</b><span class="status">'+esc(labels[status]||status)+'</span></div><p><b>'+esc(o.negocios?.nombre||"Tienda")+'</b> · '+money(o.total)+' (envío '+money(o.costo_envio)+')</p>'+progress+'<p>'+((o.detalle_pedido||[]).map(d=>esc(d.nombre_producto)+' × '+esc(d.cantidad)).join("<br>"))+'</p><small>'+new Date(o.creado_en).toLocaleString("es-SV")+'</small>'+(status==="recibido"?'<button class="btn btn-outline" data-cancel="'+esc(o.id)+'">Cancelar pedido</button>':'')+'</article>'};modal("Mis pedidos",'<div class="orders-toolbar"><span>'+orders.length+' pedido(s)</span><button class="btn btn-outline" id="refreshBuyerOrders">Actualizar</button></div>'+(orders.length?orders.map(renderOrder).join(""):'<p>Aún no tienes pedidos. Tus compras aparecerán aquí.</p>'));if($("#refreshBuyerOrders"))$("#refreshBuyerOrders").onclick=()=>ordersModal();$("#modal").querySelectorAll("[data-cancel]").forEach(b=>b.onclick=async()=>{if(!confirm("¿Cancelar este pedido y devolver el stock?"))return;b.disabled=true;const {error}=await db.rpc("cancelar_pedido_comprador",{p_pedido_id:b.dataset.cancel});if(error){notify(error.message);b.disabled=false}else{notify("Pedido cancelado");ordersModal()}})}
